function skim(address token) external {
        require(msg.sender == skimRecipient, NotAuthorized());
        require(token != address(box), CannotSkimBoxShares());
        uint256 balance = IERC20(token).balanceOf(address(this));
        SafeERC20Lib.safeTransfer(token, skimRecipient, balance);
        emit Skim(token, balance);
    }

function allocate(bytes memory data, uint256 assets, bytes4, address) external returns (bytes32[] memory, int256) {
        require(data.length == 0, InvalidData());
        require(msg.sender == parentVault, NotAuthorized());

        if (assets > 0) IERC4626(box).deposit(assets, address(this));
        // Safe casts because bounded by Vault V2 which requires totalAssets to stay below ~10^35
        uint256 newTotalAssets = _updateTotalAssets();
        int256 newAllocation = newTotalAssets.toInt256();
        int256 oldAllocation = allocation().toInt256();

        return (ids(), newAllocation - oldAllocation);
    }

function deallocate(bytes memory data, uint256 assets, bytes4, address) external returns (bytes32[] memory, int256) {
        require(data.length == 0, InvalidData());
        require(msg.sender == parentVault, NotAuthorized());

        if (assets > 0) IERC4626(box).withdraw(assets, address(this), address(this));
        // Safe casts because bounded by Vault V2 which requires totalAssets to stay below ~10^35
        uint256 newTotalAssets = _updateTotalAssets();
        int256 newAllocation = newTotalAssets.toInt256();
        int256 oldAllocation = allocation().toInt256();

        return (ids(), newAllocation - oldAllocation);
    }

function allocation() public view returns (uint256) {
        return IVaultV2(parentVault).allocation(adapterId);
    }

function updateTotalAssets() external {
        require(
            IVaultV2(parentVault).isAllocator(msg.sender) ||
                IVaultV2(parentVault).isSentinel(msg.sender) ||
                totalAssetsTimestamp + 1 days < block.timestamp,
            NotAuthorized()
        );

        uint256 oldTotalAssets = totalAssets;
        uint256 newTotalAssets = _updateTotalAssets();
        emit UpdateTotalAsset(oldTotalAssets, newTotalAssets);
    }

function _updateTotalAssets() internal returns (uint256 newTotalAssets) {
        newTotalAssets = box.previewRedeem(box.balanceOf(address(this)));
        totalAssets = newTotalAssets;
        totalAssetsTimestamp = block.timestamp;
    }

function ids() public view returns (bytes32[] memory) {
        bytes32[] memory ids_ = new bytes32[](1);
        ids_[0] = adapterId;
        return ids_;
    }

function registerNewEncryptionKey(bytes memory _key) external onlyRole(KEY_MANAGER_ROLE) {
        if (_key.length != 33) revert ErrorInvalidEncryptionKeyLength();
        uint256 _keyId = encryptionKeys.length;

        // The message from `nextCrossDomainMessageIndex` will utilise the newly registered encryption key.
        uint256 _msgIndex = IL1MessageQueueV2(messageQueueV2).nextCrossDomainMessageIndex();
        encryptionKeys.push(EncryptionKey(_msgIndex, _key));

        emit NewEncryptionKey(_keyId, _msgIndex, _key);
    }

function _afterFinalizeBatch(
        uint256 batchIndex,
        bytes32 batchHash,
        uint256 totalL1MessagesPoppedOverall,
        bytes32 postStateRoot,
        bytes32 withdrawRoot
    ) internal {
        lastFinalizedBatchIndex = batchIndex;

        if (totalL1MessagesPoppedOverall > 0) {
            IL1MessageQueueV2(messageQueueV2).finalizePoppedCrossDomainMessage(totalL1MessagesPoppedOverall);
        }

        emit FinalizeBatch(batchIndex, batchHash, postStateRoot, withdrawRoot);
    }

function _finalizeBundle(
        bytes calldata batchHeader,
        uint256 totalL1MessagesPoppedOverall,
        bytes calldata aggrProof
    ) internal virtual {
        // actions before verification
        (uint256 version, bytes32 batchHash, uint256 batchIndex, uint256 prevBatchIndex) = _beforeFinalizeBatch(
            batchHeader
        );

        // L1 message hashes are chained,
        // this hash commits to the whole queue up to and including `totalL1MessagesPoppedOverall-1`
        bytes32 messageQueueHash = totalL1MessagesPoppedOverall == 0
            ? bytes32(0)
            : IL1MessageQueueV2(messageQueueV2).getMessageRollingHash(totalL1MessagesPoppedOverall - 1);

        bytes32 postStateRoot = stateRoots[batchIndex];
        bytes32 withdrawRoot = withdrawRoots[batchIndex];

        // Get the encryption key at the time of on-chain message queue index.
        bytes memory encryptionKey = totalL1MessagesPoppedOverall == 0
            ? _getEncryptionKey(0)
            : _getEncryptionKey(totalL1MessagesPoppedOverall - 1);

        bytes memory publicInputs = abi.encodePacked(
            layer2ChainId,
            messageQueueHash,
            uint32(batchIndex - prevBatchIndex), // numBatches
            stateRoots[prevBatchIndex], // _prevStateRoot
            committedBatches[prevBatchIndex], // _prevBatchHash
            postStateRoot,
            batchHash,
            withdrawRoot,
            encryptionKey
        );

        // verify bundle, choose the correct verifier based on the last batch
        // our off-chain service will make sure all unfinalized batches have the same batch version.
        IRollupVerifier(verifier).verifyBundleProof(version, batchIndex, aggrProof, publicInputs);

        // actions after verification
        _afterFinalizeBatch(batchIndex, batchHash, totalL1MessagesPoppedOverall, postStateRoot, withdrawRoot);
    }

function _beforeFinalizeBatch(bytes calldata batchHeader)
        internal
        view
        returns (
            uint256 version,
            bytes32 batchHash,
            uint256 batchIndex,
            uint256 prevBatchIndex
        )
    {
        uint256 batchPtr;
        // compute pending batch hash and verify
        (batchPtr, batchHash, batchIndex) = _loadBatchHeader(batchHeader, lastCommittedBatchIndex);

        // make sure don't finalize batch multiple times
        prevBatchIndex = lastFinalizedBatchIndex;
        if (batchIndex <= prevBatchIndex) revert ErrorBatchIsAlreadyVerified();

        version = BatchHeaderValidiumV0Codec.getVersion(batchPtr);
    }

function _getEncryptionKey(uint256 _msgIndex) internal view returns (bytes memory) {
        // Start from the "latest" key and continue fetching keys until we find the key
        // that was rotated before the message index we have been provided.
        uint256 _numKeys = encryptionKeys.length;
        if (_numKeys == 0) revert ErrorUnknownEncryptionKey();
        EncryptionKey memory _encryptionKey = encryptionKeys[--_numKeys];

        while (_encryptionKey.msgIndex > _msgIndex) {
            if (_numKeys == 0) revert ErrorUnknownEncryptionKey();
            _encryptionKey = encryptionKeys[--_numKeys];
        }

        return _encryptionKey.key;
    }

function _depositMint(uint256 assets, uint256 shares, address receiver) internal {
        require(_cachedNavDepth == 0, ErrorsLib.ReentryNotAllowed());
        _onlyFeeder();
        _requireNotShutdown();
        _requireNonZeroAddress(receiver);

        IERC20(asset).safeTransferFrom(msg.sender, address(this), assets);
        _mint(receiver, shares);

        emit Deposit(msg.sender, receiver, assets, shares);
    }

function maxWithdraw(address owner_) external view returns (uint256) {
        uint256 ownerAssets = convertToAssets(balanceOf(owner_));
        uint256 availableLiquidity = IERC20(asset).balanceOf(address(this));
        return ownerAssets < availableLiquidity ? ownerAssets : availableLiquidity;
    }

function maxRedeem(address owner_) external view returns (uint256) {
        uint256 ownerShares = balanceOf(owner_);
        uint256 availableLiquidity = IERC20(asset).balanceOf(address(this));
        uint256 liquidityShares = convertToShares(availableLiquidity);
        return ownerShares < liquidityShares ? ownerShares : liquidityShares;
    }

function _withdrawRedeem(uint256 assets, uint256 shares, address receiver, address owner_) internal {
        require(_cachedNavDepth == 0, ErrorsLib.ReentryNotAllowed());
        _requireNonZeroAddress(receiver);

        if (msg.sender != owner_) {
            uint256 allowed = allowance(owner_, msg.sender);
            if (allowed < shares) revert ErrorsLib.InsufficientAllowance();
            if (allowed != type(uint256).max) {
                _approve(owner_, msg.sender, allowed - shares);
            }
        }

        if (balanceOf(owner_) < shares) revert ErrorsLib.InsufficientShares();
        if (IERC20(asset).balanceOf(address(this)) < assets) revert ErrorsLib.InsufficientLiquidity();

        _burn(owner_, shares);
        IERC20(asset).safeTransfer(receiver, assets);

        emit Withdraw(msg.sender, receiver, owner_, assets, shares);
    }

function skim(IERC20 token) external nonReentrant {
        require(msg.sender == skimRecipient, ErrorsLib.OnlySkimRecipient());
        _requireNotEqualAddress(address(token), asset);
        require(!isToken(token), ErrorsLib.CannotSkimToken());

        uint256 balance;

        if (address(token) != address(0)) {
            // ERC-20 tokens
            balance = token.balanceOf(address(this));
            require(balance > 0, ErrorsLib.CannotSkimZero());
            token.safeTransfer(skimRecipient, balance);
        } else {
            // ETH
            balance = address(this).balance;
            require(balance > 0, ErrorsLib.CannotSkimZero());
            (bool ok, ) = skimRecipient.call{value: balance}("");
            require(ok, ErrorsLib.TransferFailed());
        }

        emit EventsLib.Skim(token, skimRecipient, balance);
    }

function allocate(
        IERC20 token,
        uint256 assetsAmount,
        ISwapper swapper,
        bytes calldata data
    ) public nonReentrant returns (uint256 expected, uint256 received) {
        _startNavCache();

        bool winddown = isWinddown();
        require((isAllocator[msg.sender] && !winddown) || (winddown && _debtBalance(token) > 0), ErrorsLib.OnlyAllocatorsOrWinddown());
        _requireIsToken(token);

        uint256 oraclePrice = oracles[token].price();
        uint256 slippageTolerance = winddown ? _winddownSlippageTolerance() : maxSlippage;

        if (winddown) {
            // Limit allocation to debt shortfall adjusted for slippage tolerance
            uint256 debtAmount = _debtBalance(token);
            uint256 existingBalance = token.balanceOf(address(this));
            uint256 neededTokens = debtAmount > existingBalance ? debtAmount - existingBalance : 0;
            uint256 neededValue = neededTokens.mulDiv(oraclePrice, ORACLE_PRECISION, Math.Rounding.Ceil);
            uint256 maxAllocation = neededValue.mulDiv(PRECISION, PRECISION - slippageTolerance, Math.Rounding.Ceil);
            require(assetsAmount <= maxAllocation, ErrorsLib.InvalidAmount());
        }

        // Execute swap
        (uint256 assetsSpent, uint256 tokensReceived) = _executeSwap(IERC20(asset), token, assetsAmount, swapper, data);

        // Calculate and validate slippage
        uint256 expectedTokens = assetsAmount.mulDiv(ORACLE_PRECISION, oraclePrice, Math.Rounding.Ceil);
        uint256 minTokens = _calculateMinAmount(expectedTokens, slippageTolerance);
        require(tokensReceived >= minTokens, ErrorsLib.AllocationTooExpensive());

        int256 slippagePct = _calculateSlippagePct(expectedTokens, tokensReceived);

        // Track slippage if we are not in winddown and have positive slippage
        if (!winddown && tokensReceived < expectedTokens) {
            uint256 slippageValue = (expectedTokens - tokensReceived).mulDiv(oraclePrice, ORACLE_PRECISION, Math.Rounding.Ceil);
            _increaseSlippage(slippageValue.mulDiv(PRECISION, totalAssets(), Math.Rounding.Ceil));
        }

        emit EventsLib.Allocation(token, assetsSpent, expectedTokens, tokensReceived, slippagePct, swapper, data);

        _endNavCache();
        return (expectedTokens, tokensReceived);
    }

function deallocate(
        IERC20 token,
        uint256 tokensAmount,
        ISwapper swapper,
        bytes calldata data
    ) external nonReentrant returns (uint256 expected, uint256 received) {
        _startNavCache();

        bool winddown = isWinddown();
        require((isAllocator[msg.sender] && !winddown) || (winddown && _debtBalance(token) == 0), ErrorsLib.OnlyAllocatorsOrWinddown());
        _requireIsToken(token);

        uint256 oraclePrice = oracles[token].price();
        uint256 slippageTolerance = winddown ? _winddownSlippageTolerance() : maxSlippage;

        // Execute swap
        (uint256 tokensSpent, uint256 assetsReceived) = _executeSwap(token, IERC20(asset), tokensAmount, swapper, data);

        // Calculate and validate slippage
        uint256 expectedAssets = tokensAmount.mulDiv(oraclePrice, ORACLE_PRECISION, Math.Rounding.Ceil);
        uint256 minAssets = _calculateMinAmount(expectedAssets, slippageTolerance);
        require(assetsReceived >= minAssets, ErrorsLib.TokenSaleNotGeneratingEnoughAssets());

        int256 slippagePct = _calculateSlippagePct(expectedAssets, assetsReceived);

        // Track slippage if not in winddown and we have positive slippage
        if (!winddown && assetsReceived < expectedAssets) {
            // slippage is already in asset units
            uint256 slippageValue = expectedAssets - assetsReceived;
            _increaseSlippage(slippageValue.mulDiv(PRECISION, totalAssets(), Math.Rounding.Ceil));
        }

        emit EventsLib.Deallocation(token, tokensSpent, expectedAssets, assetsReceived, slippagePct, swapper, data);

        _endNavCache();
        return (expectedAssets, assetsReceived);
    }

function reallocate(
        IERC20 from,
        IERC20 to,
        uint256 tokensAmount,
        ISwapper swapper,
        bytes calldata data
    ) external nonReentrant returns (uint256 expected, uint256 received) {
        _startNavCache();

        _onlyAllocator();
        _requireNotWinddown();
        _requireIsToken(from);
        _requireIsToken(to);

        uint256 fromOraclePrice = oracles[from].price();
        uint256 toOraclePrice = oracles[to].price();

        // Execute swap
        (uint256 fromSpent, uint256 toReceived) = _executeSwap(from, to, tokensAmount, swapper, data);

        // Calculate expected amounts and validate slippage
        uint256 fromValue = tokensAmount.mulDiv(fromOraclePrice, ORACLE_PRECISION, Math.Rounding.Ceil);
        uint256 expectedToTokens = fromValue.mulDiv(ORACLE_PRECISION, toOraclePrice, Math.Rounding.Ceil);
        uint256 minToTokens = _calculateMinAmount(expectedToTokens, maxSlippage);
        require(toReceived >= minToTokens, ErrorsLib.ReallocationSlippageTooHigh());

        int256 slippagePct = _calculateSlippagePct(expectedToTokens, toReceived);

        // Track slippage if we have positive slippage
        // Note: No winddown check needed as reallocate cannot be called during winddown
        if (toReceived < expectedToTokens) {
            uint256 slippageValue = (expectedToTokens - toReceived).mulDiv(toOraclePrice, ORACLE_PRECISION, Math.Rounding.Ceil);
            _increaseSlippage(slippageValue.mulDiv(PRECISION, totalAssets(), Math.Rounding.Ceil));
        }

        emit EventsLib.Reallocation(from, to, fromSpent, expectedToTokens, toReceived, slippagePct, swapper, data);

        _endNavCache();
        return (expectedToTokens, toReceived);
    }

function flash(IERC20 flashToken, uint256 flashAmount, bytes calldata data) external {
        _onlyAllocatorOrWinddown();
        _requireNonZeroAddress(address(flashToken));
        _requireIsTokenOrAsset(flashToken);
        // Prevent re-entrancy. Can't use nonReentrant modifier because of conflict with allocate/deallocate/reallocate
        require(_cachedNavDepth == 0, ErrorsLib.ReentryNotAllowed());

        // Cache NAV before starting flash operation for slippage calculations
        _startNavCache();

        // Transfer flash amount FROM caller TO this contract
        flashToken.safeTransferFrom(msg.sender, address(this), flashAmount);

        // Call the callback function on the caller
        IBoxFlashCallback(msg.sender).onBoxFlash(flashToken, flashAmount, data);

        // Repay the flash loan by transferring back TO caller
        flashToken.safeTransfer(msg.sender, flashAmount);

        _endNavCache();

        emit EventsLib.Flash(msg.sender, flashToken, flashAmount);
    }

function addToken(IERC20 token, IOracle oracle) external {
        timelocked();
        _requireNonZeroAddress(address(token));
        _requireNotEqualAddress(address(token), asset);
        require(address(oracle) != address(0), ErrorsLib.OracleRequired());
        require(!isToken(token), ErrorsLib.TokenAlreadyWhitelisted());
        require(tokens.length < MAX_TOKENS, ErrorsLib.TooManyTokens());

        tokens.push(token);
        oracles[token] = oracle;

        emit EventsLib.TokenAdded(token, oracle);
    }

function addFunding(IFunding fundingModule) external {
        timelocked();
        require(!fundingMap[fundingModule], ErrorsLib.AlreadyWhitelisted());
        _requireNonZeroAddress(address(fundingModule));
        // Check that Box is the owner of the funding module
        (bool success, bytes memory data) = address(fundingModule).staticcall(abi.encodeWithSignature("owner()"));
        require(success && data.length == 32, ErrorsLib.InvalidValue());
        address fundingOwner = abi.decode(data, (address));
        require(fundingOwner == address(this), ErrorsLib.InvalidValue());
        require(fundingModule.facilitiesLength() == 0, ErrorsLib.NotClean());
        require(fundingModule.collateralTokensLength() == 0, ErrorsLib.NotClean());
        require(fundingModule.debtTokensLength() == 0, ErrorsLib.NotClean());

        fundingMap[fundingModule] = true;
        fundings.push(fundingModule);

        emit EventsLib.FundingModuleAdded(fundingModule);
    }

function removeFunding(IFunding fundingModule) external {
        _onlyCurator();
        _requireIsFunding(fundingModule);

        require(fundingModule.facilitiesLength() == 0, ErrorsLib.CannotRemove());
        require(fundingModule.collateralTokensLength() == 0, ErrorsLib.CannotRemove());
        require(fundingModule.debtTokensLength() == 0, ErrorsLib.CannotRemove());

        fundingMap[fundingModule] = false;
        uint256 index = _findFundingIndex(fundingModule);
        fundings[index] = fundings[fundings.length - 1];
        fundings.pop();

        emit EventsLib.FundingModuleRemoved(fundingModule);
    }

function _nav() internal view returns (uint256 nav) {
        require(_cachedNavDepth == 0, ErrorsLib.NoNavDuringCache());
        nav = IERC20(asset).balanceOf(address(this));

        // Add value of all tokens
        uint256 length = tokens.length;
        for (uint256 i; i < length; i++) {
            IERC20 token = tokens[i];
            IOracle oracle = oracles[token];
            uint256 tokenBalance = token.balanceOf(address(this));
            if (tokenBalance > 0) {
                nav += tokenBalance.mulDiv(oracle.price(), ORACLE_PRECISION);
            }
        }
        // Loop over funding sources
        length = fundings.length;
        for (uint256 i; i < length; i++) {
            IFunding funding = fundings[i];
            nav += funding.nav(IOracleCallback(address(this)));
        }
    }

function _isTokenUsedInFunding(IERC20 token) internal view returns (bool) {
        uint256 length = fundings.length;
        for (uint256 i; i < length; i++) {
            IFunding funding = fundings[i];
            if (funding.isCollateralToken(token) || funding.isDebtToken(token)) {
                return true;
            }
        }
        return false;
    }

function _debtBalance(IERC20 debtToken) internal view returns (uint256 totalDebt) {
        uint256 length = fundings.length;
        for (uint256 i; i < length; i++) {
            IFunding funding = fundings[i];
            totalDebt += funding.debtBalance(debtToken);
        }
    }

function _onlyFeeder() internal view {
        require(isFeeder[msg.sender], ErrorsLib.OnlyFeeders());
    }

function convertToAssets(uint256 shares) public view returns (uint256) {
        uint256 supply = totalSupply();
        return shares.mulDiv(totalAssets() + 1, supply + virtualShares, Math.Rounding.Floor);
    }

function convertToShares(uint256 assets) public view returns (uint256) {
        uint256 supply = totalSupply();
        return assets.mulDiv(supply + virtualShares, totalAssets() + 1, Math.Rounding.Floor);
    }

function isToken(IERC20 token) public view returns (bool) {
        return address(oracles[token]) != address(0);
    }

function _increaseSlippage(uint256 slippagePct) internal {
        // Reset epoch if expired
        if (block.timestamp >= slippageEpochStart + slippageEpochDuration) {
            slippageEpochStart = block.timestamp;
            accumulatedSlippage = slippagePct;
            emit EventsLib.SlippageEpochReset(block.timestamp);
        } else {
            accumulatedSlippage += slippagePct;
        }

        require(accumulatedSlippage < maxSlippage, ErrorsLib.TooMuchAccumulatedSlippage());

        emit EventsLib.SlippageAccumulated(slippagePct, accumulatedSlippage);
    }

function _startNavCache() internal {
        if (_cachedNavDepth == 0) {
            _cachedNav = _nav();
        }
        _cachedNavDepth++;
    }

function _endNavCache() internal {
        _cachedNavDepth--;
    }

function isWinddown() public view returns (bool) {
        return shutdownTime != type(uint256).max && block.timestamp >= shutdownTime + shutdownWarmup;
    }

function _winddownSlippageTolerance() internal view returns (uint256) {
        uint256 timeElapsed = block.timestamp - shutdownWarmup - shutdownTime;
        return
            (timeElapsed < shutdownSlippageDuration)
                ? timeElapsed.mulDiv(MAX_SLIPPAGE_LIMIT, shutdownSlippageDuration)
                : MAX_SLIPPAGE_LIMIT;
    }

function totalAssets() public view returns (uint256) {
        return _cachedNavDepth > 0 ? _cachedNav : _nav();
    }

function _onlyAllocator() internal view {
        require(isAllocator[msg.sender], ErrorsLib.OnlyAllocators());
    }

function _onlyAllocatorOrWinddown() internal view {
        require(isAllocator[msg.sender] || isWinddown(), ErrorsLib.OnlyAllocatorsOrWinddown());
    }

function timelocked() internal {
        require(executableAt[msg.data] > 0, ErrorsLib.DataNotTimelocked());
        require(block.timestamp >= executableAt[msg.data], ErrorsLib.TimelockNotExpired());

        executableAt[msg.data] = 0;

        emit EventsLib.TimelockExecuted(bytes4(msg.data), msg.data, msg.sender);
    }

function _onlyCurator() internal view {
        require(msg.sender == curator, ErrorsLib.OnlyCurator());
    }

function _findFundingIndex(IFunding fundingModule) internal view returns (uint256) {
        uint256 length = fundings.length;
        for (uint256 i = 0; i < length; i++) {
            if (fundings[i] == fundingModule) {
                return i;
            }
        }
        revert ErrorsLib.NotWhitelisted();
    }

function pledge(bytes calldata facilityData, IERC20 collateralToken, uint256 collateralAmount) external override {
        require(msg.sender == owner, ErrorsLib.OnlyOwner());
        require(isFacility(facilityData), ErrorsLib.NotWhitelisted());
        require(isCollateralToken(collateralToken), ErrorsLib.TokenNotWhitelisted());

        IERC20(collateralToken).forceApprove(address(pool), collateralAmount);
        pool.supply(address(collateralToken), collateralAmount, address(this), 0);
        pool.setUserUseReserveAsCollateral(address(collateralToken), true);
    }

function depledge(bytes calldata facilityData, IERC20 collateralToken, uint256 collateralAmount) external override {
        require(msg.sender == owner, ErrorsLib.OnlyOwner());
        require(isFacility(facilityData), ErrorsLib.NotWhitelisted());
        require(isCollateralToken(collateralToken), ErrorsLib.TokenNotWhitelisted());

        pool.withdraw(address(collateralToken), collateralAmount, owner);
    }

function borrow(bytes calldata facilityData, IERC20 debtToken, uint256 borrowAmount) external override {
        require(msg.sender == owner, ErrorsLib.OnlyOwner());
        require(isFacility(facilityData), ErrorsLib.NotWhitelisted());
        require(isDebtToken(debtToken), ErrorsLib.TokenNotWhitelisted());

        pool.borrow(address(debtToken), borrowAmount, rateMode, 0, address(this));
        debtToken.safeTransfer(owner, borrowAmount);
    }

function repay(bytes calldata facilityData, IERC20 debtToken, uint256 repayAmount) external override {
        require(msg.sender == owner, ErrorsLib.OnlyOwner());
        require(isFacility(facilityData), ErrorsLib.NotWhitelisted());
        require(isDebtToken(debtToken), ErrorsLib.TokenNotWhitelisted());

        debtToken.forceApprove(address(pool), repayAmount);
        uint256 actualRepaid = pool.repay(address(debtToken), repayAmount, rateMode, address(this));

        if (actualRepaid < repayAmount) {
            debtToken.safeTransfer(owner, repayAmount - actualRepaid);
        }
    }

function ltv(bytes calldata data) external view override returns (uint256) {
        (uint256 totalCollateralBase, uint256 totalDebtBase, , , , ) = pool.getUserAccountData(address(this));

        return totalCollateralBase == 0 ? 0 : totalDebtBase.wDivUp(totalCollateralBase);
    }

function _debtBalance(IERC20 debtToken) internal view override returns (uint256 balance) {
        (, , , , , , , , , , address variableDebtToken, , , , ) = pool.getReserveData(address(debtToken));
        return IERC20(variableDebtToken).balanceOf(address(this));
    }

function _collateralBalance(IERC20 collateralToken) internal view override returns (uint256 balance) {
        (, , , , , , , , address aTokenAddress, , , , , , ) = pool.getReserveData(address(collateralToken));
        return IERC20(aTokenAddress).balanceOf(address(this));
    }

function _afterAddLiquidity(
        address sender,
        PoolKey calldata key,
        IPoolManager.ModifyLiquidityParams calldata params,
        BalanceDelta,
        BalanceDelta,
        bytes calldata
    ) internal virtual override returns (bytes4, BalanceDelta) {
        // Get the position key
        bytes32 positionKey = Position.calculatePositionKey(sender, params.tickLower, params.tickUpper, params.salt);

        // Record the block number when the liquidity was added
        lastAddedLiquidity[key.toId()][positionKey] = block.number;

        return (this.afterAddLiquidity.selector, BalanceDeltaLibrary.ZERO_DELTA);
    }

function _afterRemoveLiquidity(
        address sender,
        PoolKey calldata key,
        IPoolManager.ModifyLiquidityParams calldata params,
        BalanceDelta,
        BalanceDelta feeDelta,
        bytes calldata
    ) internal virtual override returns (bytes4, BalanceDelta) {
        PoolId id = key.toId();

        bytes32 positionKey = Position.calculatePositionKey(sender, params.tickLower, params.tickUpper, params.salt);

        uint128 liquidity = poolManager.getLiquidity(id);

        // We need to check if the liquidity is greater than 0 to prevent donating when there are no liquidity positions.
        if (block.number - lastAddedLiquidity[id][positionKey] < blockNumberOffset && liquidity > 0) {
            // If the liquidity provider removes liquidity before the block number offset, the hook donates
            // a part of the fees to the pool (i.e., in range liquidity providers at the time of liquidity removal).

            BalanceDelta liquidityPenalty = _calculateLiquidityPenalty(feeDelta, id, positionKey);

            BalanceDelta deltaHook = poolManager.donate(
                key, uint256(int256(liquidityPenalty.amount0())), uint256(int256(liquidityPenalty.amount1())), ""
            );

            BalanceDelta returnDelta = toBalanceDelta(-deltaHook.amount0(), -deltaHook.amount1());

            return (this.afterRemoveLiquidity.selector, returnDelta);
        }

        return (this.afterRemoveLiquidity.selector, BalanceDeltaLibrary.ZERO_DELTA);
    }

function _calculateLiquidityPenalty(BalanceDelta feeDelta, PoolId poolId, bytes32 positionKey)
        internal
        virtual
        returns (BalanceDelta liquidityPenalty)
    {
        int128 amount0FeeDelta = feeDelta.amount0();
        int128 amount1FeeDelta = feeDelta.amount1();

        // amount0 and amount1 are necesseraly greater than or equal to 0, since they are fee rewards
        // This is the implementation of a linear penalty on the fees, where the penalty decreases linearly from 100% of the fees at the block
        // where liquidity was added to the pool to 0% after the block number offset.
        // The formula is:
        // liquidityPenalty = feeDelta * ( 1 - (block.number - lastAddedLiquidity[id][positionKey]) / blockNumberOffset)
        // NOTE: this function is called only if the liquidity is removed before the block number offset, i.e.,
        // block.number - lastAddedLiquidity[poolId][positionKey] < blockNumberOffset
        // so the subtraction is safe and won't overflow
        uint256 amount0LiquidityPenalty = FullMath.mulDiv(
            SafeCast.toUint128(amount0FeeDelta),
            blockNumberOffset - (block.number - lastAddedLiquidity[poolId][positionKey]), // wont't overflow, since block.number - lastAddedLiquidity[poolId][positionKey] < blockNumberOffset
            blockNumberOffset
        );
        uint256 amount1LiquidityPenalty = FullMath.mulDiv(
            SafeCast.toUint128(amount1FeeDelta),
            blockNumberOffset - (block.number - lastAddedLiquidity[poolId][positionKey]),
            blockNumberOffset
        );

        // although the amounts are returned as uint256, they must fit in int128, since they are fee rewards
        liquidityPenalty = toBalanceDelta(amount0LiquidityPenalty.toInt128(), amount1LiquidityPenalty.toInt128());
    }

function _beforeSwap(
        address sender,
        PoolKey calldata key,
        IPoolManager.SwapParams calldata params,
        bytes calldata hookData
    ) internal override returns (bytes4, BeforeSwapDelta, uint24) {
        PoolId poolId = key.toId();
        Checkpoint storage _lastCheckpoint = _lastCheckpoints[poolId];

        // update the top-of-block `slot0` if new block
        if (_lastCheckpoint.blockNumber != uint48(block.number)) {
            _lastCheckpoint.slot0 = Slot0.wrap(poolManager.extsload(StateLibrary._getPoolStateSlot(poolId)));
            return (this.beforeSwap.selector, BeforeSwapDeltaLibrary.ZERO_DELTA, 0);
        }

        return super._beforeSwap(sender, key, params, hookData);
    }

function _afterSwap(
        address sender,
        PoolKey calldata key,
        IPoolManager.SwapParams calldata params,
        BalanceDelta delta,
        bytes calldata hookData
    ) internal override returns (bytes4, int128) {
        uint48 blockNumber = uint48(block.number);
        PoolId poolId = key.toId();
        Checkpoint storage _lastCheckpoint = _lastCheckpoints[poolId];

        // after the first swap in block, initialize the temporary pool state
        if (_lastCheckpoint.blockNumber != blockNumber) {
            _lastCheckpoint.blockNumber = blockNumber;

            // iterate over ticks
            (, int24 tickAfter,,) = poolManager.getSlot0(poolId);
            for (int24 tick = _lastCheckpoint.slot0.tick(); tick < tickAfter; tick += key.tickSpacing) {
                (
                    uint128 liquidityGross,
                    int128 liquidityNet,
                    uint256 feeGrowthOutside0X128,
                    uint256 feeGrowthOutside1X128
                ) = poolManager.getTickInfo(poolId, tick);

                _lastCheckpoint.state.ticks[tick].liquidityGross = liquidityGross;
                _lastCheckpoint.state.ticks[tick].liquidityNet = liquidityNet;
                _lastCheckpoint.state.ticks[tick].feeGrowthOutside0X128 = feeGrowthOutside0X128;
                _lastCheckpoint.state.ticks[tick].feeGrowthOutside1X128 = feeGrowthOutside1X128;
            }

            // deep copy only values that are used and change in fair delta calculation
            _lastCheckpoint.state.slot0 = Slot0.wrap(poolManager.extsload(StateLibrary._getPoolStateSlot(poolId)));
            (_lastCheckpoint.state.feeGrowthGlobal0X128, _lastCheckpoint.state.feeGrowthGlobal1X128) =
                poolManager.getFeeGrowthGlobals(poolId);
            _lastCheckpoint.state.liquidity = poolManager.getLiquidity(poolId);
        }
        int128 unspecifiedAmount = (params.amountSpecified < 0 == params.zeroForOne) ? delta.amount1() : delta.amount0();

        if (unspecifiedAmount < 0) {
            unspecifiedAmount = -unspecifiedAmount;
        }

        // update target output if it exceeds the swap amount
        if (_targetOutput > uint128(unspecifiedAmount)) {
            _targetOutput = uint128(unspecifiedAmount);
        }

        return super._afterSwap(sender, key, params, delta, hookData);
    }

function _getTargetOutput(address, PoolKey calldata key, IPoolManager.SwapParams calldata params, bytes calldata)
        internal
        override
        returns (uint256 targetOutput, bool applyTargetOutput)
    {
        PoolId poolId = key.toId();
        Checkpoint storage _lastCheckpoint = _lastCheckpoints[poolId];

        // constant bid price
        if (!params.zeroForOne) {
            _lastCheckpoint.state.slot0 = _lastCheckpoint.slot0;
        }

        // calculate target output
        // NOTE: this functions does not execute the swap, it only calculates the output of a swap in the given state
        (BalanceDelta targetDelta,,,) = Pool.swap(
            _lastCheckpoint.state,
            Pool.SwapParams({
                tickSpacing: key.tickSpacing,
                zeroForOne: params.zeroForOne,
                amountSpecified: params.amountSpecified,
                sqrtPriceLimitX96: params.sqrtPriceLimitX96,
                lpFeeOverride: 0
            })
        );

        int128 target =
            (params.amountSpecified < 0 == params.zeroForOne) ? targetDelta.amount1() : targetDelta.amount0();

        targetOutput = uint256(uint128(target));
        applyTargetOutput = true;
    }

function transferFrom(address sender, address recipient, uint256 amount) public override returns (bool) {
        // Check if the recipient is agentBalances to prevent recursion
        if (recipient == address(agentBalances)) {
            return super.transferFrom(sender, recipient, amount);
        }

        address distributor = address(deployer.distributor());

        if (address(deployer) != address(0) &&                               // deployer exists
        (recipient.isContract() || sender.isContract()) &&                   // XOR: exactly one must be a contract
        !(recipient == address(deployer) || sender == address(deployer)) &&  // neither sender nor recipient is deployer
        (distributor == address(0) || recipient != distributor))
        {
            uint256 taxAmount = (amount * taxPercentage) / 10000;
            uint256 amountAfterTax = amount - taxAmount;

            //send the tax to deployer to distribute
            super.transferFrom(sender, address(deployer), taxAmount);
            deployer.accumulateSwapFees(taxAmount);

            // Transfer the remaining amount to the recipient
            return super.transferFrom(sender, recipient, amountAfterTax);
        } else {
            // No tax if recipient is not a contract
            return super.transferFrom(sender, recipient, amount);
        }
    }

function getAgentCreator(address agentToken) external view returns (address) {
        return IOctoDistributor(address(deployer.distributor())).agentCreators(agentToken);
    }

function requestImage(
        address agentToken,
        string calldata prompt,
        uint256 width,
        uint256 height
    ) external nonReentrant onlyValidAgent(agentToken) {
        AgentConfig memory config = agentConfigs[agentToken];
        require(config.isConfigured, "Agent not configured");
        require(bytes(prompt).length > 0, "Prompt cannot be empty");
        require(width >= 64 && height >= 64, "Width and height must be greater or equal than 64");
        IERC20Upgradeable token = IERC20Upgradeable(agentToken);

        // Generate request ID from prompt and timestamp
        bytes32 requestId = keccak256(abi.encodePacked(prompt, block.timestamp, msg.sender));

        // Transfer tokens from user to this contract
        token.safeTransferFrom(msg.sender, address(this), config.pricePerImage);

        // Record the request
        imageRequests[agentToken][requestId] = ImageRequest({
            user: msg.sender,
            amount: config.pricePerImage,
            width: width,
            height: height,
            timestamp: block.timestamp,
            fulfilled: 0,
            refunded: 0,
            prompt: prompt
        });

        // Add to pending fees instead of accumulated
        pendingFees[agentToken] += config.pricePerImage;

        emit ImageRequested(agentToken, msg.sender, requestId, config.pricePerImage, width, height, prompt);
    }

function fulfillImage(
        address agentToken,
        bytes32 requestId
    ) external onlyAgentOwner(agentToken) onlyValidAgent(agentToken) nonReentrant {
        ImageRequest storage request = imageRequests[agentToken][requestId];
        require(request.fulfilled == 0 && request.refunded == 0, "Request already processed");
        require(request.user != address(0), "Request does not exist");

        request.fulfilled = block.timestamp;

        // Move fee from pending to accumulated
        pendingFees[agentToken] -= request.amount;
        uint256 treasuryCut = (request.amount * parameters[Parameter.TREASURY_CUT]) / 10000;
        accumulatedFees[agentToken] += (request.amount - treasuryCut);
        IERC20Upgradeable(agentToken).safeTransfer(spectralTreasury, (request.amount * parameters[Parameter.TREASURY_CUT]) / 10000);

        emit ImageFulfilled(agentToken, requestId);
    }

function requestRefund(
        address agentToken,
        bytes32 requestId
    ) external nonReentrant {
        ImageRequest storage request = imageRequests[agentToken][requestId];
        AgentConfig memory config = agentConfigs[agentToken];

        require(request.user == msg.sender, "Not request owner");
        require(request.fulfilled == 0 && request.refunded == 0, "Request already processed");
        require(
            block.timestamp >= request.timestamp + config.refundTimeLimit,
            "Refund time limit not reached"
        );

        request.refunded = block.timestamp;

        // Remove from pending fees
        pendingFees[agentToken] -= request.amount;

        // Transfer tokens back to user
        IERC20Upgradeable(agentToken).safeTransfer(msg.sender, request.amount);

        emit RefundIssued(agentToken, requestId, request.amount);
    }

function withdrawFees(address agentToken) external onlyAgentOwner(agentToken) nonReentrant {
        uint256 amount = accumulatedFees[agentToken];
        require(amount > 0, "No fees to withdraw");

        accumulatedFees[agentToken] = 0;
        IERC20Upgradeable(agentToken).safeTransfer(msg.sender, amount);

        emit FeesWithdrawn(agentToken, amount);
    }

function deployAgent(
        string memory _agentName,
        string memory _agentTicker,
        uint256 specAmount
    ) public payable whenNotPaused {
        require(msg.value >=
        parameters[Parameter.DEPLOYMENT_COST_ETH]
        , "Incorrect ETH amount");

        // Transfer SPEC from the deployer to this contract
        IERC20Upgradeable(spectralToken).transferFrom(msg.sender, address(this), specAmount);

        // Deploy the agent and perform common operations
        (address _agentToken, uint256 creatorTokensReceived) = initializeAgent(
            _agentName,
            _agentTicker,
            specAmount
        );

        //allocate tokens to the creator
        IERC20Upgradeable(_agentToken).transfer(msg.sender, creatorTokensReceived);

        // Emit tokens sold event for initial token sale
        emit TokensSold(_agentToken, msg.sender, creatorTokensReceived, specAmount);        
    }

function deployAgentWithETH(
        string memory _agentName,
        string memory _agentTicker,
        uint256 minSpecAmount
    ) public payable whenNotPaused returns (address agentToken) {
        require(msg.value >= 
        parameters[Parameter.DEPLOYMENT_COST_ETH]
        , "Incorrect ETH amount");

        // Calculate ETH required for fees and deduct from the total ETH received
        uint256 treasuryFee = parameters[Parameter.DEPLOYMENT_TREASURY_FEE];
        uint256 initialTradingBalance = parameters[Parameter.INITIAL_TRADING_BALANCE];
        uint256 totalFees = initialTradingBalance + treasuryFee;

        require(msg.value >= totalFees, "Insufficient ETH for fees");

        uint256 swapAmountETH = msg.value - totalFees;

        // Perform the swap using the externally calculated minSpecAmount as the minimum output
        uint256 specAmount = swapETHForSPEC(swapAmountETH, minSpecAmount);
        // Deploy the agent and perform common operations
        (address _agentToken, uint256 creatorTokensReceived) = initializeAgent(
            _agentName,
            _agentTicker,
            specAmount
        );
        agentToken = _agentToken;

        if (specAmount > 0) {
            IERC20Upgradeable(_agentToken).transfer(msg.sender, creatorTokensReceived);
            emit TokensSold(_agentToken, msg.sender, creatorTokensReceived, specAmount);
        }
    }

function initializeAgent(
        string memory _agentName,
        string memory _agentTicker,
        uint256 specAmount
    ) internal returns (address, uint256) {
        require(address(agentBalances) != address(0), "Invalid balances address");

        // Deploy the proxy with the AgentToken implementation address with diamond pattern
        address _agentToken = createBeaconProxy(agentTokenImplementation, abi.encodeWithSelector(
            AgentToken(address(0)).initialize.selector,
            _agentName,
            _agentTicker,
            parameters[Parameter.INITIAL_TOKEN_SUPPLY],
            feeWallet,
            address(agentBalances)
        ));

        agentTokens[_agentToken] = true;
        distributor.setAgentCreator(_agentToken, msg.sender);
        // Transfer deployment fee and treasury fee to feeWallet
        IERC20Upgradeable(_agentToken).transfer(feeWallet, parameters[Parameter.AGENT_TOKEN_DEPLOYMENT_FEE]);

        IERC20Upgradeable(_agentToken).approve(address(spectralStaking), 2_000_000 ether);
        spectralStaking.addDistribution(_agentToken, address(0), 2_000_000 ether, 0);

        IERC20Upgradeable(_agentToken).approve(address(agentBalances), parameters[Parameter.AGENT_TOKEN_OWNERSHIP]);
        agentBalances.deposit(address(this), _agentToken, _agentToken, parameters[Parameter.AGENT_TOKEN_OWNERSHIP]);
        // Calculate tokens received based on `specAmount`
        uint256 creatorTokensReceived = getTokensReceived(specAmount, _agentToken);
        require(creatorTokensReceived <= parameters[Parameter.INITIAL_TOKEN_SUPPLY] / 100, "Exceeds 1%");

        (bool success, ) = feeWallet.call{value: parameters[Parameter.DEPLOYMENT_TREASURY_FEE]}("");
        require(success, "Transfer failed.");

        // Deposit the initial trading balance to agent balance contract
        agentBalances.depositETH{value: parameters[Parameter.INITIAL_TRADING_BALANCE]}(_agentToken);

        // Update total SPEC deposited and tokens sold
        totalSPECDeposited[_agentToken] += specAmount;
        agentTokensSold[_agentToken] += creatorTokensReceived;

        // Account for deployment fee and ownership tokens in the tracking
        agentTokensSold[_agentToken] += parameters[Parameter.AGENT_TOKEN_DEPLOYMENT_FEE];
        agentTokensSold[_agentToken] += parameters[Parameter.AGENT_TOKEN_OWNERSHIP];
        // Emit agent deployment event
        emit AgentDeployed(_agentToken);

        return (_agentToken, creatorTokensReceived);
    }

function swapETHForSPEC(uint256 ethAmount, uint256 minSpecAmount) internal returns (uint256 specAmount) {
        if(ethAmount == 0){
            return 0;
        }

        ISwapRouter.ExactInputSingleParams memory params = ISwapRouter.ExactInputSingleParams({
            tokenIn: WETH,
            tokenOut: spectralToken,
            fee: 3000,
            recipient: address(this),
            amountIn: ethAmount,
            amountOutMinimum: minSpecAmount,
            sqrtPriceLimitX96: 0
        });

        specAmount = uniswapV3Router.exactInputSingle{value: ethAmount}(params);

        require(specAmount >= minSpecAmount, "received less than expected");
        return specAmount;
    }

function _getTokensFromUniswap(uint _amountIn, address _tokenIn, address _tokenOut) internal view returns (uint256) {
        address[] memory path = new address[](2);
        path[0] = _tokenIn;
        path[1] = _tokenOut;

        uint256[] memory amounts = uniswapRouter.getAmountsOut(_amountIn, path);
        return amounts[amounts.length - 1];
    }

function _getTokensFromBondingCurve(uint _amountIn, address _agentToken, bool isSpecToAgentToken) internal view returns (uint256) {
        uint256 currentSPECReserve = totalSPECDeposited[_agentToken] + INITIAL_VIRTUAL_LIQUIDITY;
        uint256 currentTokenReserve = IERC20Upgradeable(_agentToken).balanceOf(address(this));

        // Determine reserves based on input direction
        uint256 newReserve;
        uint256 k = currentSPECReserve * currentTokenReserve;

        if (isSpecToAgentToken) {
            // Calculate new SPEC reserve and agent token received
            newReserve = currentSPECReserve + _amountIn;
            uint256 newTokenReserve = k / newReserve;
            return currentTokenReserve - newTokenReserve;
        } else {
            // Calculate new agent token reserve and SPEC received
            newReserve = currentTokenReserve + _amountIn;
            uint256 newSPECReserve = k / newReserve;
            return currentSPECReserve - newSPECReserve;
        }
    }

function _createUniswapPool(address _agentToken, uint _deadline) internal {
        require(totalSPECDeposited[_agentToken] > UNISWAP_POOL_CREATION_VALUE && agentTokenUniswapPool[_agentToken] == address(0), "Invalid pool creation conditions");
        address poolAddress = deployUniswapPool(_agentToken);
        if(agentTokenUniswapPool[_agentToken] != address(0))
        {
            agentTokenUniswapPool[_agentToken] = poolAddress;
            uint256 agentTokenBalance = IERC20Upgradeable(_agentToken).balanceOf(address(this));
            // Approve tokens and add liquidity
            IERC20Upgradeable(spectralToken).approve(address(uniswapRouter), totalSPECDeposited[_agentToken]);
            IERC20Upgradeable(_agentToken).approve(address(uniswapRouter), agentTokenBalance);
            uniswapRouter.addLiquidity(
                spectralToken,
                _agentToken,
                totalSPECDeposited[_agentToken],
                agentTokenBalance,
                0, 
                0,
                address(agentBalances), //agentBalances will burn the LPs by the Agent Wallet
                _deadline
            );
        }
    }

function swapExactSPECForTokens(uint _amountIn, uint amountOutMin, address _agentToken, uint _deadline) public ensure(_deadline) whenNotPaused nonReentrant {   
        require(agentTokens[_agentToken], "Invalid agent token");
        require(_amountIn > 0, "Invalid amount");
        uint256 taxSpecAmount = (_amountIn * AgentToken(_agentToken).taxPercentage() / 10000);
        uint256 userSpecAmount = _amountIn - taxSpecAmount;
        IERC20Upgradeable(spectralToken).transferFrom(msg.sender, address(this), _amountIn);
        if(agentTokenUniswapPool[_agentToken] != address(0)) {
            address[] memory path = new address[](2);
            path[0] = spectralToken;
            path[1] = _agentToken;

            IERC20Upgradeable(spectralToken).approve(address(uniswapRouter), userSpecAmount);

            //We won't emit an event here because Uniswap's event has all the info we need
            //Uniswap checks if amount received > amountOutMin
            uniswapRouter.swapExactTokensForTokensSupportingFeeOnTransferTokens(userSpecAmount, amountOutMin, path, msg.sender, _deadline);
        } else {
            uint256 tokensReceived = getTokensReceived(userSpecAmount, _agentToken);
            require(tokensReceived >= amountOutMin, "Insufficient tokens output");
            agentTokensSold[_agentToken] += tokensReceived;
            totalSPECDeposited[_agentToken] += userSpecAmount;
            IERC20Upgradeable(_agentToken).safeTransfer(msg.sender, tokensReceived);
            emit TokensSold(_agentToken, msg.sender, tokensReceived, _amountIn);
        }
        _distributeSwapFees(taxSpecAmount);
        //Create liquidity pool if we meet liquidity conditions
        if(totalSPECDeposited[_agentToken] > UNISWAP_POOL_CREATION_VALUE && agentTokenUniswapPool[_agentToken] == address(0)) {
            _createUniswapPool(_agentToken, _deadline);
        }
    }

function swapExactTokensForSPEC(uint amountIn, uint amountOutMin, address fromToken, uint deadline) public ensure(deadline) whenNotPaused nonReentrant {
        require(agentTokens[fromToken], "Invalid agent token");
        require(amountIn > 0, "Invalid amount");
        uint256 taxAmount = (amountIn * AgentToken(fromToken).taxPercentage() / 10000);
        uint256 protocolSwapAmount = taxAmount + accumulatedTaxToSwapByAgent[fromToken];
        accumulatedTaxToSwapByAgent[fromToken] = 0;
        uint256 userSwapAfterTax = amountIn - taxAmount;
        uint256 actualSpecTax;
        IERC20Upgradeable(fromToken).safeTransferFrom(msg.sender, address(this), amountIn);
        if(agentTokenUniswapPool[fromToken] != address(0)) {
            address[] memory path = new address[](2);
            path[0] = fromToken;
            path[1] = spectralToken;
            IERC20Upgradeable(fromToken).approve(address(uniswapRouter), userSwapAfterTax);


            //Uniswap checks if amount received > amountOutMin
            uniswapRouter.swapExactTokensForTokensSupportingFeeOnTransferTokens(userSwapAfterTax, amountOutMin, path, msg.sender, deadline);

            //Swap the current tax and accumulated tax that was from outside our protocol operations (since this contract is ignored in the conditions of the agentToken tax taking)
            uint256 protocolSpecAmount = getSPECReceived(protocolSwapAmount, fromToken);
            uint256 initialSpecBalance = IERC20(spectralToken).balanceOf(address(this));
            IERC20Upgradeable(fromToken).approve(address(uniswapRouter), protocolSwapAmount);
            uniswapRouter.swapExactTokensForTokensSupportingFeeOnTransferTokens(protocolSwapAmount, (protocolSpecAmount * 95) / 100, path, address(this), deadline);
            uint256 specBalance = IERC20(spectralToken).balanceOf(address(this)) - initialSpecBalance;
            actualSpecTax = specBalance;
        } else {
            uint256 userSpecAmount = getSPECReceived(userSwapAfterTax, fromToken);
            require(userSpecAmount >= amountOutMin, "Insufficient SPEC output");
            agentTokensSold[fromToken] -= userSwapAfterTax;
            totalSPECDeposited[fromToken] -= userSpecAmount;
            IERC20Upgradeable(spectralToken).safeTransfer(msg.sender, userSpecAmount);
            uint256 protocolSpecAmount = getSPECReceived(protocolSwapAmount, fromToken);
            agentTokensSold[fromToken] -= protocolSwapAmount;
            totalSPECDeposited[fromToken] -= protocolSpecAmount;
            actualSpecTax = protocolSpecAmount;
            emit TokensRedeemedForSPEC(fromToken, msg.sender, userSwapAfterTax, userSpecAmount);
        }
        if(actualSpecTax == 0) {
            return;
        }
        _distributeSwapFees(actualSpecTax);
    }

function _distributeSwapFees(uint256 specAmount) internal {
        uint256 splitAmount = specAmount / 2;
        IERC20(spectralToken).transfer(feeWallet, splitAmount);
        IERC20(spectralToken).approve(address(spectralStaking), splitAmount);
        spectralStaking.addDistributionToBuffer(spectralToken, address(0), splitAmount, 0);
        emit TaxDistributed(specAmount);
    }

function distributeTradingProfitsToStakers(uint256 _amount, address _token) external onlyDistributor {
        require(_token != address(0), "ZERO_ADDRESS");
        require(_amount > 0, "AMOUNT_ZERO");
        require(address(spectralStaking) != address(0), "STAKING_ADDRESS_ZERO");
        IERC20Upgradeable(_token).safeTransferFrom(msg.sender, address(this), _amount);
        IERC20Upgradeable(_token).approve(address(spectralStaking),_amount);
        spectralStaking.addDistribution(_token, address(0), _amount, 0);
        emit ProfitDistributed(_token, _amount);
    }

function deployUniswapPool(address token) internal whenNotPaused returns(address) {
        address pair;
        try IUniswapV2Factory(uniswapFactory).createPair(token, spectralToken) returns (address createdPair) {
            pair = createdPair;
            agentTokenUniswapPool[token] = pair;
            emit UniswapV2PoolCreated(token, pair);
            return pair;
        } catch {
            pair = IUniswapV2Factory(uniswapFactory).getPair(token, spectralToken);
            emit UniswapV2PoolCreationFailed(token, pair);
            return address(0);
        }
    }

function getTokensReceived(uint _amountSPECIn, address _agentToken) public view returns (uint256) {
        require(agentTokens[_agentToken], "Invalid agent token");

        if (agentTokenUniswapPool[_agentToken] != address(0)) {
            return _getTokensFromUniswap(_amountSPECIn, spectralToken, _agentToken);
        }
        return _getTokensFromBondingCurve(_amountSPECIn, _agentToken, true);
    }

function getSPECReceived(uint _amountAgentTokenIn, address _agentToken) public view returns (uint256) {
        require(agentTokens[_agentToken], "Invalid agent token");

        if (agentTokenUniswapPool[_agentToken] != address(0)) {
            return _getTokensFromUniswap(_amountAgentTokenIn, _agentToken, spectralToken);
        }
        return _getTokensFromBondingCurve(_amountAgentTokenIn, _agentToken, false);
    }

function fillOrder(
        uint96 pendingOrderIdx,
        uint96 orderId,
        address target,
        bytes calldata txData
    ) external override {
        //fetch order
        Order memory order = orders[orderId];

        require(
            order.orderId == pendingOrderIds[pendingOrderIdx],
            "Order Fill Mismatch"
        );

        //perform swap
        (uint256 amountOut, uint256 tokenInRefund) = execute(
            target,
            txData,
            order
        );

        //handle accounting
        //remove from array
        pendingOrderIds = ArrayMutation.removeFromArray(
            pendingOrderIdx,
            pendingOrderIds
        );

        //handle fee
        (uint256 feeAmount, uint256 adjustedAmount) = applyFee(
            amountOut,
            order.feeBips
        );
        if (feeAmount != 0) {
            order.tokenOut.safeTransfer(address(MASTER), feeAmount);
        }

        //send tokenOut to recipient
        order.tokenOut.safeTransfer(order.recipient, adjustedAmount);

        //refund any unspent tokenIn
        //this should generally be 0 when using exact input for swaps, which is recommended
        if (tokenInRefund != 0) {
            order.tokenIn.safeTransfer(order.recipient, tokenInRefund);
        }
    }

function _cancelOrder(Order memory order) internal returns (bool) {
        for (uint96 i = 0; i < pendingOrderIds.length; i++) {
            if (pendingOrderIds[i] == order.orderId) {
                //remove from pending array
                pendingOrderIds = ArrayMutation.removeFromArray(
                    i,
                    pendingOrderIds
                );

                //refund tokenIn amountIn to recipient
                order.tokenIn.safeTransfer(order.recipient, order.amountIn);

                //emit event
                emit OrderCancelled(order.orderId);

                return true;
            }
        }
        return false;
    }

function _modifyOrder(
        uint96 orderId,
        IERC20 _tokenOut,
        uint256 amountInDelta,
        uint256 _minAmountOut,
        address _recipient,
        bool increasePosition,
        bool permit,
        bytes calldata permitPayload
    ) internal {
        //fetch order
        Order memory order = orders[orderId];

        require(msg.sender == order.recipient, "only order owner");

        //deduce any amountIn changes
        uint256 newAmountIn = order.amountIn;
        if (amountInDelta != 0) {
            if (increasePosition) {
                //take more tokens from order recipient
                newAmountIn += amountInDelta;
                procureTokens(
                    order.tokenIn,
                    amountInDelta,
                    order.recipient,
                    permit,
                    permitPayload
                );
            } else {
                //refund some tokens
                //ensure delta is valid
                require(amountInDelta < order.amountIn, "invalid delta");

                //set new amountIn for accounting
                newAmountIn -= amountInDelta;

                //refund position partially
                order.tokenIn.safeTransfer(order.recipient, amountInDelta);
            }
        }

        //construct new order
        Order memory newOrder = Order({
            orderId: orderId,
            tokenIn: order.tokenIn,
            tokenOut: _tokenOut,
            amountIn: newAmountIn,
            minAmountOut: _minAmountOut,
            feeBips: order.feeBips,
            recipient: _recipient
        });

        //store new order
        orders[orderId] = newOrder;
    }

function procureTokens(
        IERC20 token,
