function stake(uint256 amount) public {
    exitRewardPool();
    updateValuePerShare();

    // now we can issue shares
    lpToken.safeTransferFrom(msg.sender, address(this), amount);
    uint256 sharesToIssue = amount.mul(unit).div(valuePerShare);
    totalShares = totalShares.add(sharesToIssue);
    share[msg.sender] = share[msg.sender].add(sharesToIssue);

    uint256 oldValuePerShare = valuePerShare;

    // Rate needs to be updated here, otherwise the valuePerShare would be incorrect.
    updateValuePerShare();

    emit Staked(msg.sender, amount, sharesToIssue, oldValuePerShare, valuePerShare, balanceOf(msg.sender));

    restakeIntoRewardPool();
  }

function exit() public {
    exitRewardPool();
    updateValuePerShare();

    // now we can transfer funds and burn shares
    uint256 toTransfer = balanceOf(msg.sender);
    lpToken.safeTransfer(msg.sender, toTransfer);
    totalShares = totalShares.sub(share[msg.sender]);
    share[msg.sender] = 0;
    emit Withdrawn(msg.sender, toTransfer);
    // Rate needs to be updated here, otherwise the valuePerShare would be incorrect.
    updateValuePerShare();

    restakeIntoRewardPool();
  }

function earned(address account) external view returns (uint256) {
    if (totalShares == 0) {
      return 0;
    }
    uint256 totalBalance = rewardPool.balanceOf(address(this));
    uint256 totalEarn = rewardPool.earned(address(this));
    uint256 perShare = totalBalance.add(totalEarn).mul(unit).div(totalShares);

    return perShare.mul(share[account]).div(unit);
  }

function updateValuePerShare() internal {
    if (totalShares == 0) {
      totalValue = 0;
      valuePerShare = unit;
    } else {
      totalValue = lpToken.balanceOf(address(this));
      valuePerShare = totalValue.mul(unit).div(totalShares);
    }
  }

function exitRewardPool() internal {
    if(rewardPool.balanceOf(address(this)) != 0){
      // exit and do accounting first
      rewardPool.exit();
    }
  }

function restakeIntoRewardPool() internal {
    if(lpToken.balanceOf(address(this)) != 0){
      // stake back to the pool
      lpToken.safeApprove(address(rewardPool), 0);
      lpToken.safeApprove(address(rewardPool), lpToken.balanceOf(address(this)));
      rewardPool.stake(lpToken.balanceOf(address(this)));
    }
  }

function balanceOf(address who) public view returns(uint256) {
    return valuePerShare.mul(share[who]).div(unit);
  }

function _notifyPoolRewardAmounts(uint _poolRewardAmount) private {
        uint _surplusRewardAmount = _poolRewardAmount;
        uint _rewardAmount = 0;
        address farmAddr;

        for (uint i = 0; i < stakingTokens.length; i++) {
            StakingRewardsInfo memory info = stakingRewardsInfoByStakingToken[stakingTokens[i]];
            if(info.rewardRate <= 0){
                continue;
            }
            if(stakingTokens[i] == rewardsToken){
                farmAddr = info.stakingRewards;
                continue;
            }
            _rewardAmount = _poolRewardAmount.mul(info.rewardRate).div(10000);
            if(_rewardAmount >= _surplusRewardAmount){
                _rewardAmount = _surplusRewardAmount;
            }
            _surplusRewardAmount = _surplusRewardAmount.sub(_rewardAmount);
            _notifyRewardAmount(info.stakingRewards,_rewardAmount);
        }
        _surplusRewardAmount = IERC20(rewardsToken).balanceOf(address(this));
        if(_surplusRewardAmount > 0 && farmAddr != address(0)){
            _notifyRewardAmount(farmAddr,_surplusRewardAmount);
        }
    }

function _notifyRewardAmount(address _stakingToken,uint _rewardAmount) private {
        require(_stakingToken != address(0), 'StakingRewardsFactory::notifyRewardAmount: not deployed');

        if (_rewardAmount > 0) {
            require(
                IERC20(rewardsToken).transfer(_stakingToken, _rewardAmount),
                'StakingRewardsFactory::notifyRewardAmount: transfer failed'
            );
            StakingRewards(_stakingToken).notifyRewardAmount(_rewardAmount);
        }
    }

function _reserveRewards(address _account,uint _rawRewardsAmount) private {
        require(_account != address(0), 'StakingRewardsFactory::_reserveRewards: not deployed');

        require(
            IERC20(rewardsToken).transfer(_account, _rawRewardsAmount),
            'StakingRewardsFactory::_reserveRewards: transfer failed'
        );
    }

function _mint(uint _mintAmount) private {
        require(_mintAmount > 0, 'StakingRewardsFactory::_mint: mintAmount is zero');

        IMinterV2ERC20(rewardsToken).mint(address(this), _mintAmount);
    }

function mint(address dst, uint rawAmount) external {
        require(msg.sender == minter, "BT::mint: only the minter can mint");
        require(dst != address(0), "BT::mint: cannot transfer to the zero address");

        // mint the amount
        uint96 amount = safe96(rawAmount, "BT::mint: amount exceeds 96 bits");
        require(maxTotalSupply >= SafeMath.add(totalSupply, amount), "BT::mint: exceeded max totalSupply");
        totalSupply = safe96(SafeMath.add(totalSupply, amount), "BT::mint: totalSupply exceeds 96 bits");

        // transfer the amount to the recipient
        balances[dst] = add96(balances[dst], amount, "BT::mint: transfer amount overflows");
        emit Transfer(address(0), dst, amount);

        // move delegates
        _moveDelegates(address(0), delegates[dst], amount);
    }

function _moveDelegates(address srcRep, address dstRep, uint96 amount) internal {
        if (srcRep != dstRep && amount > 0) {
            if (srcRep != address(0)) {
                uint32 srcRepNum = numCheckpoints[srcRep];
                uint96 srcRepOld = srcRepNum > 0 ? checkpoints[srcRep][srcRepNum - 1].votes : 0;
                uint96 srcRepNew = sub96(srcRepOld, amount, "BT::_moveVotes: vote amount underflows");
                _writeCheckpoint(srcRep, srcRepNum, srcRepOld, srcRepNew);
            }

            if (dstRep != address(0)) {
                uint32 dstRepNum = numCheckpoints[dstRep];
                uint96 dstRepOld = dstRepNum > 0 ? checkpoints[dstRep][dstRepNum - 1].votes : 0;
                uint96 dstRepNew = add96(dstRepOld, amount, "BT::_moveVotes: vote amount overflows");
                _writeCheckpoint(dstRep, dstRepNum, dstRepOld, dstRepNew);
            }
        }
    }

