function lastTimeRewardApplicable() public view returns (uint) {
        return Math.min(block.timestamp, periodFinish);
    }

function _collect(uint tokenId) internal {
        PositionManagerV3.CollectParams memory _claim = PositionManagerV3.CollectParams(tokenId, owner, type(uint128).max, type(uint128).max);
        (uint amount0, uint amount1) = nftManager.collect(_claim);
        emit Collect(msg.sender, tokenId, amount0, amount1);
    }

function earned(uint tokenId) public view returns (uint claimable, uint32 secondsInside, uint160 secondsPerLiquidityInside) {
        uint _reward = rewardPerSecond() - tokenRewardPerSecondPaid[tokenId];
        claimable = rewards[tokenId];
        time memory _elapsed = elapsed[tokenId];
        (secondsPerLiquidityInside, secondsInside) = _getSecondsInside(tokenId);
        uint _maxSecondsInside = lastUpdateTime - Math.min(_elapsed.timestamp, periodFinish);
        uint _secondsInside = Math.min((secondsPerLiquidityInside - _elapsed.secondsPerLiquidityInside) * liquidityOf[tokenId], _maxSecondsInside);
        uint _fullSecondsInside = secondsInside - _elapsed.secondsInside;
        if (_fullSecondsInside > _maxSecondsInside && _secondsInside > 0) {
            _secondsInside = _secondsInside * _maxSecondsInside / _fullSecondsInside;
        }
        if (totalLiquidity > 0 && _secondsInside > 0) {
            claimable += (_reward * _secondsInside * UniV3(pool).liquidity() / totalLiquidity);
        }
    }

function deposit(uint tokenId) external update(tokenId) {
        (,,address token0, address token1,uint24 fee,,,uint128 _liquidity,,,,) = nftManager.positions(tokenId);
        address _pool = PoolAddress.computeAddress(factory,PoolAddress.PoolKey({token0: token0, token1: token1, fee: fee}));

        require(pool == _pool);
        require(_liquidity > 0);

        liquidityOf[tokenId] = _liquidity;
        totalLiquidity += _liquidity;
        owners[tokenId] = msg.sender;
        tokenIds[msg.sender].push(tokenId);

        nftManager.transferFrom(msg.sender, address(this), tokenId);

        emit Deposit(msg.sender, tokenId, _liquidity);
    }

function _withdraw(uint tokenId) internal {
        require(owners[tokenId] == msg.sender);
        uint _liquidity = liquidityOf[tokenId];
        liquidityOf[tokenId] = 0;
        totalLiquidity -= _liquidity;
        owners[tokenId] = address(0);
        _remove(tokenIds[msg.sender], tokenId);
        nftManager.safeTransferFrom(address(this), msg.sender, tokenId);

        emit Withdraw(msg.sender, tokenId, _liquidity);
    }

function _getRecipient(uint tokenId) internal view returns (address) {
        if (owners[tokenId] != address(0)) {
            return owners[tokenId];
        } else {
            return nftManager.ownerOf(tokenId);
        }
    }

function _getSecondsInside(uint256 tokenId) internal view returns (uint160 secondsPerLiquidityInside, uint32 secondsInside) {
        (,,,,,int24 tickLower,int24 tickUpper,,,,,) = nftManager.positions(tokenId);
        (,secondsPerLiquidityInside,secondsInside) = UniV3(pool).snapshotCumulativesInside(tickLower, tickUpper);
    }

function rewardPerSecond() public view returns (uint) {
        return rewardPerSecondStored + ((lastTimeRewardApplicable() - lastUpdateTime) * rewardRate);
    }

function vote()
        isOwner(msg.sender)
        public override returns (bool) {
        VoteProgress memory progress = _voteProgress;
        require(progress.requestId > 0, "C98MSiG: No pending request");
        if (_votes[msg.sender] < progress.requestId) {
            _votes[msg.sender] = progress.requestId;
            progress.currentVote += _votePowers[msg.sender];
            _voteProgress = progress;
            emit Voted(msg.sender, progress.requestId, progress.currentVote, progress.requiredVote);
        }
        if (progress.currentVote >= progress.requiredVote) {
            Request memory req = _request;
            (bool success,) = req.destination.call{value: req.value}(req.data);
            if (success) {
                delete _request;
                delete _voteProgress;
                Executed(true, progress.requestId, req.destination, req.value, req.data);
            }
            else {
                Executed(false, progress.requestId, req.destination, req.value, req.data);
            }
        }
        return true;
    }

function getPrice() public view override returns (uint) {
        (, int priceAnswer,, uint timeStamp,) = priceAggregator.latestRoundData();

        require(timeStamp > 0 && timeStamp <= block.timestamp, "PriceFeed: price timestamp from aggregator is 0, or in future");
        require(priceAnswer >= 0, "PriceFeed: price answer from aggregator is negative");

        uint8 answerDigits = priceAggregator.decimals();
        uint price = uint256(priceAnswer);

        // currently the Aggregator returns an 8-digit precision, but we handle the case of future changes
        if (answerDigits > TARGET_DIGITS) { 
            price = price.div(10 ** (answerDigits - TARGET_DIGITS));
        }
        else if (answerDigits < TARGET_DIGITS) {
            price = price.mul(10 ** (TARGET_DIGITS - answerDigits));
        } 
        return price;
    }

function getCurrentICR(address _borrower, uint _price) public view override returns (uint) {
        uint pendingETHReward = getPendingETHReward(_borrower);
        uint pendingLUSDDebtReward = getPendingLUSDDebtReward(_borrower);

        uint currentETH = Troves[_borrower].coll.add(pendingETHReward);
        uint currentLUSDDebt = Troves[_borrower].debt.add(pendingLUSDDebtReward);

        uint ICR = LiquityMath._computeCR(currentETH, currentLUSDDebt, _price);
        return ICR;
    }

function liquidateTroves(uint _n) external override {
        LocalVariables_OuterLiquidationFunction memory L;

        LiquidationTotals memory T;

        L.price = priceFeed.getPrice();
        L.LUSDInStabPool = stabilityPool.getTotalLUSDDeposits();
        L.recoveryModeAtStart = checkRecoveryMode();

        // Perform the appropriate liquidation sequence - tally the values, and obtain their totals
        if (L.recoveryModeAtStart == true) {
            T = _getTotalsFromLiquidateTrovesSequence_RecoveryMode(L.price, L.LUSDInStabPool, _n);
        } else if (L.recoveryModeAtStart == false) {
            T = _getTotalsFromLiquidateTrovesSequence_NormalMode(L.price, L.LUSDInStabPool, _n);
        }

        // Move liquidated ETH and LUSD to the appropriate pools
        stabilityPool.offset(T.totalDebtToOffset, T.totalCollToSendToSP);
        _redistributeDebtAndColl(T.totalDebtToRedistribute, T.totalCollToRedistribute);

        // Update system snapshots and the final partially liquidated trove, if there is one
        _updateSystemSnapshots_excludeCollRemainder(T.partialNewColl.add(T.totalCollGasCompensation));
        _updatePartiallyLiquidatedTrove(T.partialAddr, T.partialNewDebt, T.partialNewColl, T.partialUpperHint, T. partialLowerHint, L.price);

        L.liquidatedDebt = T.totalDebtInSequence.sub(T.partialNewDebt);
        L.liquidatedColl = T.totalCollInSequence.sub(T.totalCollGasCompensation).sub(T.partialNewColl);
        emit Liquidation(L.liquidatedDebt, L.liquidatedColl, T.totalCollGasCompensation, T.totalLUSDGasCompensation);

        // Send gas compensation to caller
        _sendGasCompensation(msg.sender, T.totalLUSDGasCompensation, T.totalCollGasCompensation);
    }

function batchLiquidateTroves(address[] memory _troveArray) public override {
        require(_troveArray.length != 0, "TroveManager: Calldata address array must not be empty");

        LocalVariables_OuterLiquidationFunction memory L;
