                blockCurrentWeek - 1 weeks
            );
            data.governance.feeDistributor.tradingWeekTotalSupply = feeDistributor
                .totalSupplyAtTimestamp(blockCurrentWeek);
            for (uint256 i = 0; i < 3; i++) {
